export type IconName = keyof typeof UI_ICONS;
export type BrandIconName = keyof typeof BRAND_ICONS;

/** A glyph from the interface set. Decorative: hidden from assistive tech, so pair it with text. */
export function Icon({ name, size = 16, className = "" }: { name: IconName; size?: number; className?: string }) {
  return (
    <svg
      viewBox="0 0 56 56"
      width={size}
      height={size}
      className={className}
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: UI_ICONS[name] }}
    />
  );
}

/** A tool or company mark. Tinted by `color` (any CSS colour) and otherwise inherits the text colour. */
export function BrandIcon({
  name,
  size = 16,
  className = "",
  color,
}: {
  name: BrandIconName;
  size?: number;
  className?: string;
  color?: string;
}) {
  return (
    <svg
      viewBox="0 0 24 24"
      width={size}
      height={size}
      className={className}
      style={color ? { color } : undefined}
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: BRAND_ICONS[name] }}
    />
  );
}
